-- PT113-S3-Q11. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT113-S3-Q11$batch03$ AND q.stimulus=$batch03$Several thousand years ago, people in what is now North America began to grow corn, which grows faster and produces more food per unit of land than do the grains these people had grown previously. Corn is less nutritious than those other grains, however, and soon after these people established corn as their staple grain crop, they began having nutrition-related health problems. Yet the people continued to grow corn as their staple grain, although they could have returned to growing the more nutritious grains.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to explain why the people mentioned continued to grow corn as their staple grain crop?$batch03$ AND q.correct_choice=$batch03$E$batch03$) THEN RAISE EXCEPTION 'Question changed: PT113-S3-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT113-S3-Q11$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S3-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT113-S3-Q11$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Corn is less nutritious than the old grains, and it caused nutrition-related health problems.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$People kept growing corn as their staple even though they could have gone back to the old grains?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Corn still has its advantage: it grows faster and yields more food per acre. If people found a way to fix the nutrition problem without giving up corn, they would keep the extra food and solve the health issue. That beats switching back.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a way to solve corn's nutrition problem while keeping corn.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT113-S3-Q11$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Comparing this corn to its ancestors does not explain why people preferred it to the other grains despite the health problems.$batch03$), ($batch03$B$batch03$, $batch03$Modern corn being more nutritious has nothing to do with people thousands of years ago.$batch03$), ($batch03$C$batch03$, $batch03$Without meat or milk, people had no other way to make up for corn's poor nutrition. That makes sticking with corn harder to explain.$batch03$), ($batch03$D$batch03$, $batch03$If some alternatives grew in poorer soil, switching back would have been even easier.$batch03$), ($batch03$E$batch03$, $batch03$People learned that adding readily available nongrain foods fixed their health. They could keep corn's higher yield and solve the nutrition problem at the same time.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT113-S3-Q11$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
